const readline = require('readline');

const rl = readline.createInterface({
    input: process.stdin,
    terminal: false
});

let inputData = [];

rl.on('line', (line) => {
    inputData = inputData.concat(line.trim().split(/\s+/).filter(x => x.length > 0));
});

rl.on('close', () => {
    let idx = 0;
    const readInt64 = () => {
        const val = BigInt(inputData[idx]);
        idx++;
        return val;
    };

    const a = new Array(9).fill(0n);

    for (let k = 1n; k <= 8n; k++) {
        const l = (1n << k) - 1n;
        const r = 1n << (k - 1n);
        const v = l * r;
        a[Number(k)] = v;
    }

    const n = readInt64();
    for (let k = 8; k >= 1; k--) {
        if (n >= a[k] && n % a[k] === 0n) {
            console.log(a[k].toString());
            return;
        }
    }
});
